def histogram(test):
    """Given a string representing space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    >>> print(histogram('a b c'))
    {'a': 1, 'b': 1, 'c': 1}
    >>> print(histogram('a b b a'))
    {'a': 2, 'b': 2}
    >>> print(histogram('a b c a b'))
    {'a': 2, 'b': 2}
    >>> print(histogram('b b b b a'))
    {'b': 4}
    >>> print(histogram(''))
    {}

    """
    if not test:
        return {}

    letter_count = {}
    for char in test.split():
        count = letter_count.get(char, 0) + 1
        letter_count[char] = count

    max_count = max(letter_count.values())
    result = {k: v for k, v in letter_count.items() if v == max_count}

    return result
```

