def tri(n):
    """Everyone knows Fibonacci sequence, it was studied deeply by mathematicians. However, what people don't know is Tribonacci sequence."""

    # Base cases for n = 0 and n = 1
    if n == 0:
        return [3]
    elif n == 1:
        return [3, 2]

    trib_sequence = [3, 2]  # Initialize the sequence with base values tri(1) and tri(2)

    for i in range(2, n + 1):
        if i % 2 == 0:
            next_value = (i // 2) + trib_sequence[i - 1]
        else:
            # Calculate the Tribonacci number using previous three numbers. Note that we need to handle index out of range for tri(n+1).
            if i < len(trib_sequence):
                next_value = (trib_sequence[i - 1] + trib_sequence[i - 2]) + trib_sequence[-3]
            else:
                # If we are calculating the Tribonacci number for n+1, which is beyond our current list size. We need to extend it by appending zeros until tri(n) exists in sequence.
                while len(trib_sequence) <= i + 2:
                    trib_sequence.append(0)
                next_value = (trib_sequence[i - 1] + trib_sequence[i - 2]) + trib_sequence[-3]

        # Append the calculated Tribonacci number to our sequence list and update it for future calculations
        trib_sequence.append(next_value)

    return trib_sequence[:n+1]

